-- 5. Permission-gate function and table-RLS facts the parity above depends on (read-only metadata).
begin read only;
select n.nspname, p.proname, p.prosecdef, p.proconfig, md5(pg_get_functiondef(p.oid)) as def_md5 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where p.proname = 'fn_costing_view_allowed';
select c.relname, c.relrowsecurity, c.relforcerowsecurity from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'costing' and c.relname in ('sku_scheme_viability_snapshot', 'scheme_master', 'sku_scheme_policy', 'scheme_policy_rules');
select tablename, policyname, cmd, roles, qual from pg_policies where schemaname = 'costing' and tablename in ('sku_scheme_viability_snapshot', 'scheme_master', 'sku_scheme_policy', 'scheme_policy_rules');
select indexname, indexdef from pg_indexes where schemaname = 'costing' and tablename = 'sku_scheme_viability_snapshot';
rollback;
